function extractOutputText(response) {
  if (typeof response === 'string') return response;
  if (response.output_text) return response.output_text;
  const parts = [];
  for (const item of response.output || []) {
    for (const content of item.content || []) {
      if (content.text) parts.push(content.text);
      if (content.type === 'output_text' && content.text) parts.push(content.text);
    }
  }
  return parts.join('\n').trim();
}

function extractObsidianExports(markdown) {
  const sectionIndex = markdown.search(/^##\s+6\.\s+Obsidian Export\s*$/m);
  const source = sectionIndex >= 0 ? markdown.slice(sectionIndex) : markdown;
  const fence = String.fromCharCode(96).repeat(3);
  const codeblockRe = new RegExp(fence + '(?:markdown)?\\s*\\n([\\s\\S]*?)' + fence, 'g');
  const blocks = [...source.matchAll(codeblockRe)].map((m) => m[1].trim());
  if (blocks.length < 2) throw new Error('OpenAI output does not contain two markdown codeblocks in Obsidian Export.');
  return { shoppingMarkdown: blocks[0], mealPlanMarkdown: blocks[1] };
}

function normalizeMealPlanExport(mealPlanMarkdown, targetDate) {
  const body = mealPlanMarkdown.trim().split(/\r?\n/).map((line) => {
    if (/^#\s+/.test(line)) return '#' + line;
    return line;
  }).join('\n').replace(/\n{3,}/g, '\n\n');
  return ('# ' + targetDate + '\n' + body + '\n').replace(/^###/gm, '##');
}

function padClock(clock) {
  const [hour, minute] = clock.split(':');
  return String(Number(hour)).padStart(2, '0') + ':' + minute;
}

function addMinutesToLocalDateTime(localDateTime, minutes) {
  const [date, time] = localDateTime.split('T');
  const [hour, minute, second] = time.split(':').map(Number);
  const total = hour * 60 + minute + minutes;
  return date + 'T' + String(Math.floor(total / 60)).padStart(2, '0') + ':' + String(total % 60).padStart(2, '0') + ':' + String(second || 0).padStart(2, '0');
}

function parseMealSections(normalizedMealPlanMarkdown, targetDateIso) {
  const meals = [];
  let current = null;
  for (const line of normalizedMealPlanMarkdown.replace(/\r\n/g, '\n').split('\n')) {
    const heading = line.match(/^##\s+(.+?)\s+\((\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})\)\s*$/);
    if (heading) {
      current = { name: heading[1], startClock: heading[2], sourceEndClock: heading[3], items: [] };
      meals.push(current);
      continue;
    }
    if (current && /^-\s+/.test(line)) current.items.push(line);
  }
  return meals.map((meal) => {
    const start = targetDateIso + 'T' + padClock(meal.startClock) + ':00';
    const slug = meal.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    return {
      eventId: ('nutrition-' + targetDateIso.replaceAll('-', '') + '-' + slug).slice(0, 100),
      title: meal.name + ' - jídelní plán',
      start,
      end: addMinutesToLocalDateTime(start, 5),
      reminderMinutes: meal.name.toLocaleLowerCase('cs-CZ') === 'snídaně' ? null : 60,
      description: meal.items.join('\n') + '\n\nAUTO-NUTRITION-PLAN'
    };
  });
}

const ctx = $('Prepare Context').first().json;
const raw = $json;
const full_response = extractOutputText(raw);
const { shoppingMarkdown, mealPlanMarkdown } = extractObsidianExports(full_response);
const normalizedMealPlan = normalizeMealPlanExport(mealPlanMarkdown, ctx.target_date);
const calendarEvents = parseMealSections(normalizedMealPlan, ctx.target_date_iso);

return [{
  json: {
    ...ctx,
    full_response,
    shopping_markdown: shoppingMarkdown,
    meal_plan_markdown: normalizedMealPlan,
    calendar_events: calendarEvents
  }
}];

const item = $input.first().json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { ...item, existing_meal_plan: buffer.toString('utf8') } }];

