return [{ json: { ...item, existing_cart: buffer.toString('utf8') } }];

function parseCzDate(value, defaultYear) {
  const match = String(value).trim().match(/^(\d{1,2})\.(\d{1,2})\.(?:\s*(\d{4}))?\.?$/);
  if (!match) return null;
  return new Date(Date.UTC(Number(match[3] || defaultYear), Number(match[2]) - 1, Number(match[1])));
}

function splitTopLevelBlocks(markdown) {
  const lines = markdown.replace(/\r\n/g, '\n').split('\n');
  const blocks = [];
  let current = [];
  for (const line of lines) {
    if (/^#\s+/.test(line) && current.length) {
      blocks.push(current.join('\n'));
      current = [line];
    } else current.push(line);
  }
  if (current.length) blocks.push(current.join('\n'));
  return blocks.filter((block) => block.trim());
}

function hasOldPlans(markdown, targetDate, year) {
  const target = parseCzDate(targetDate, year);
  return [...markdown.matchAll(/^#\s+(.+?)\s*$/gm)].some((m) => {
    const d = parseCzDate(m[1], year);
    return d && d.getTime() < target.getTime();
  });
}

const generated = $input.first().json;
const existingMealPlan = generated.existing_meal_plan || '';
const existingCart = generated.existing_cart || '';
const hasCart = existingCart.trim().length > 0 && existingCart.trim() !== generated.shopping_markdown.trim();
const needsPlanDecision = hasOldPlans(existingMealPlan, generated.target_date, Number(generated.target_date_iso.slice(0, 4)));
const needsCartDecision = hasCart;

return [{
  json: {
    ...generated,
    existing_meal_plan: existingMealPlan,
    existing_cart: existingCart,
    needs_approval: needsPlanDecision || needsCartDecision,
    needs_plan_decision: needsPlanDecision,
    needs_cart_decision: needsCartDecision,
    plan_decision: needsPlanDecision ? null : 'keep_old',
    cart_decision: needsCartDecision ? null : 'replace',
    approval_message: [
      'Jídelníček je vygenerovaný pro ' + generated.target_date + '.',
      needsPlanDecision ? 'V Jídelní plán.md jsou starší plány. Vyber, jestli je smazat nebo nechat.' : 'Starší jídelní plány nebyly nalezené.',
      needsCartDecision ? 'Nákupní košík.md už obsahuje jiný košík. Vyber nahradit nebo sloučit.' : 'Nákupní košík je prázdný nebo stejný.'
    ].join('\n')
  }
}];

