function updateMealPlanNote(existingMarkdown, newPlanMarkdown, targetDate, deleteOldPlans, currentYear) {
  const target = parseCzDate(targetDate, currentYear);
  const kept = splitTopLevelBlocks(existingMarkdown).filter((block) => {
    const heading = block.match(/^#\s+(.+?)\s*$/m);
    if (!heading) return true;
    const date = parseCzDate(heading[1], currentYear);
    if (!date) return true;
    if (date.getTime() === target.getTime()) return false;
    if (deleteOldPlans && date.getTime() < target.getTime()) return false;
    return true;
  });
  return [newPlanMarkdown.trim(), ...kept.map((b) => b.trim()).filter(Boolean)].join('\n\n').trim() + '\n';
}
function normalizeShoppingKey(text) {
  return text.replace(/\(.+?\)/g, ' ').replace(/[—-].*$/g, ' ').replace(/\b\d+(?:[,.]\d+)?\s*(ks|g|kg|ml|l|balení|síť|láhev|plechovka|kelímek)(?=\s|;|\/|\)|$)/giu, ' ').replace(/\s+/g, ' ').trim().toLocaleLowerCase('cs-CZ');
}
function extractQuantities(text) {
  return [...text.matchAll(/(\d+(?:[,.]\d+)?)\s*(ks|g|kg|ml|l|balení|síť|láhev|plechovka|kelímek)(?=\s|;|\/|\)|$)/giu)].map((m) => ({ value: Number(m[1].replace(',', '.')), unit: m[2].toLowerCase() })).filter((q) => Number.isFinite(q.value));
}
function parseShoppingItem(line, location) {
  const match = line.match(/^-\s+\[([ xX])\]\s+(.+?)\s*$/);
  if (!match) return null;
  const text = match[2].trim();
  return { line, checked: match[1].toLowerCase() === 'x', text, key: normalizeShoppingKey(text), location, quantities: extractQuantities(text) };
}
function parseShoppingList(markdown) {
  const sections = [];
  let current = null;
  for (const rawLine of markdown.replace(/\r\n/g, '\n').split('\n')) {
    const line = rawLine.trimEnd();
    const heading = line.match(/^#\s+(.+?)\s*$/);
    if (heading) {
      current = { location: heading[1], items: [] };
      sections.push(current);
      continue;
    }
    const item = parseShoppingItem(line, current?.location || 'Ostatní');
    if (item) {
      if (!current) {
        current = { location: 'Ostatní', items: [] };
        sections.push(current);
      }
      current.items.push(item);
    }
  }
  return sections;
}
function formatQuantity(value, unit) {
  const text = Number.isInteger(value) ? String(value) : String(Math.round(value * 100) / 100).replace('.', ',');
  return text + ' ' + unit;
}
function mergeShoppingItem(a, b) {
  if (!a.quantities.length || !b.quantities.length) return { ...a, line: a.line + ' | sloučeno s: ' + b.text };
  const qa = a.quantities[0], qb = b.quantities[0];
  if (qa.unit !== qb.unit) return { ...a, line: a.line + ' | sloučeno s: ' + b.text };
  const sum = qa.value + qb.value;
  return { ...a, line: a.line.replace(/(\d+(?:[,.]\d+)?)\s*(ks|g|kg|ml|l|balení|síť|láhev|plechovka|kelímek)(?=\s|;|\/|\)|$)/i, formatQuantity(sum, qa.unit)), quantities: [{ value: sum, unit: qa.unit }, ...a.quantities.slice(1)] };
}
function mergeShoppingLists(existingMarkdown, newMarkdown) {
  const oldItems = parseShoppingList(existingMarkdown).flatMap((s) => s.items).filter((i) => !i.checked);
  const newSections = parseShoppingList(newMarkdown);
  const map = new Map();
  for (const item of oldItems) map.set(item.key, { ...item, line: item.line.replace(/^-\s+\[[ xX]\]/, '- [ ]') });
  for (const section of newSections) for (const item of section.items) {
    const clean = { ...item, checked: false, line: item.line.replace(/^-\s+\[[ xX]\]/, '- [ ]') };
    map.set(clean.key, map.has(clean.key) ? { ...mergeShoppingItem(map.get(clean.key), clean), location: clean.location } : clean);
  }
  const grouped = new Map();
  for (const item of map.values()) {
    if (!grouped.has(item.location)) grouped.set(item.location, []);
    grouped.get(item.location).push(item);
  }
  return [...grouped.entries()].map(([location, items]) => ['# ' + location, ...items.map((item) => item.line)].join('\n')).join('\n') + '\n';
}

const base = $('Prepare Note Decisions').first().json;
const input = { ...base, ...$input.first().json };
const response = input.response ?? input.data ?? input;
const planDecision = response.plan_decision ?? input.plan_decision ?? 'keep_old';
const cartDecision = response.cart_decision ?? input.cart_decision ?? 'replace';
const year = Number(input.target_date_iso.slice(0, 4));
const deleteOld = planDecision === 'delete_old';
const mergedMealPlan = updateMealPlanNote(input.existing_meal_plan, input.meal_plan_markdown, input.target_date, deleteOld, year);
const mergedCart = cartDecision === 'merge' ? mergeShoppingLists(input.existing_cart, input.shopping_markdown) : input.shopping_markdown.trim() + '\n';

return [{ json: { ...input, plan_decision: planDecision, cart_decision: cartDecision, final_meal_plan: mergedMealPlan, final_cart: mergedCart } }];

const item = $input.first().json;
return [{
  json: item,
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(item.final_meal_plan, 'utf8'), 'Jídelní plán.md', 'text/markdown')
  }
}];

const item = $input.first().json;
return [{
  json: item,
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(item.final_cart, 'utf8'), 'Nákupní košík.md', 'text/markdown')
  }
}];

const final = $('Finalize Notes').first().json;
const list = $json.items || $json.calendars || $json.data?.items || $json.body?.items || [];
const existing = Array.isArray(list) ? list.find((cal) => cal.summary === final.calendar_name) : null;
return [{ json: { ...final, calendar_id: existing?.id || null, calendar_missing: !existing } }];
